};

function send(res, status, body, headers = {}) {
  res.writeHead(status, { ...securityHeaders, 'cache-control': 'no-store', ...headers });
  res.end(body);
}

const json = (res, status, obj) => send(res, status, JSON.stringify(obj), { 'content-type': 'application/json' });
