    22	export async function notifyBatch(batch, { link, partial }) {
    23	  const files = batch.files;
    24	  const total = files.reduce((n, f) => n + f.size, 0);
    25	  const isFollowUp = batch.notifiedFiles > 0;
    26	  const what = `${files.length} file${files.length === 1 ? '' : 's'} (${humanSize(total)})`;
    27	  const title = isFollowUp ? `drop: more files arrived — now ${what}` : `drop: ${what} received`;
    28	  const rows = files
    29	    .map((f) => `<li>${escapeHtml(f.name)} <span style="color:#888">— ${humanSize(f.size)}</span></li>`)
    30	    .join('');
    31	  const html = `
    32	<p><b>${what}</b> dropped${partial ? ' — the sender left before marking it done, so it may be incomplete' : ''}.</p>
    33	<p><a href="${escapeHtml(link)}">${escapeHtml(link)}</a></p>
    34	<ul>${rows}</ul>
    35	<p style="color:#888">From ${escapeHtml(senderLabel(batch))} · ${escapeHtml(batch.userAgent ?? '')}</p>`;
    36	  return send(title, html);
    37	}
