    39	let lastFullNotice = 0;
    40	
    41	// Told at most twice a day; every refused upload would be a flood otherwise.
    42	export async function notifyFull(reason, details) {
    43	  if (Date.now() - lastFullNotice < 12 * 3600_000) return;
    44	  lastFullNotice = Date.now();
